"use client";

import React, { useState } from "react";
import Link from "next/link";
import api from "@/lib/api";
import {
  Mail,
  Phone,
  MessageSquare,
  Send,
  CheckCircle2,
  AlertCircle,
  Clock,
  Sparkles,
  ShieldCheck,
  ExternalLink,
  HelpCircle,
  TrainFront,
  ArrowRight,
  Headphones,
  FileQuestion,
  Bug,
  Handshake,
  Loader2,
} from "lucide-react";

interface CategoryOption {
  id: string;
  label: string;
  icon: React.ComponentType<{ className?: string }>;
  description: string;
}

const CATEGORIES: CategoryOption[] = [
  {
    id: "general",
    label: "General Inquiry",
    icon: HelpCircle,
    description: "General questions about Trayago features or services",
  },
  {
    id: "split-journey",
    label: "Split Ticket & Booking",
    icon: TrainFront,
    description: "Help with split journey routes, station pairings or booking",
  },
  {
    id: "pnr-tracking",
    label: "PNR & Live Status",
    icon: Clock,
    description: "Questions regarding PNR confirmation or train tracking",
  },
  {
    id: "technical-bug",
    label: "Report a Bug",
    icon: Bug,
    description: "Found an error or unexpected issue in the app or website",
  },
  {
    id: "partnership",
    label: "Business & Partnership",
    icon: Handshake,
    description: "Commercial collaborations, API access, or media queries",
  },
];

export default function ContactClient() {
  const [formData, setFormData] = useState({
    name: "",
    email: "",
    phone: "",
    category: "general",
    subject: "",
    message: "",
  });

  const [loading, setLoading] = useState(false);
  const [submitted, setSubmitted] = useState(false);
  const [errorMsg, setErrorMsg] = useState<string | null>(null);

  const handleInputChange = (
    e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>
  ) => {
    const { name, value } = e.target;
    setFormData((prev) => ({ ...prev, [name]: value }));
    if (errorMsg) setErrorMsg(null);
  };

  const selectCategory = (catId: string) => {
    setFormData((prev) => ({ ...prev, category: catId }));
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setErrorMsg(null);

    // Client-side validation
    if (!formData.name.trim()) {
      setErrorMsg("Please enter your name.");
      return;
    }

    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!formData.email.trim() || !emailRegex.test(formData.email.trim())) {
      setErrorMsg("Please enter a valid email address.");
      return;
    }

    if (!formData.subject.trim()) {
      setErrorMsg("Please enter a subject.");
      return;
    }

    if (!formData.message.trim() || formData.message.trim().length < 5) {
      setErrorMsg("Please enter a detailed message (minimum 5 characters).");
      return;
    }

    setLoading(true);

    try {
      const response = await api.post("/contact", {
        name: formData.name.trim(),
        email: formData.email.trim(),
        phone: formData.phone.trim() || undefined,
        category: formData.category,
        subject: formData.subject.trim(),
        message: formData.message.trim(),
      });

      if (response.data && response.data.success) {
        setSubmitted(true);
      } else {
        setErrorMsg(
          response.data?.error || "Unable to send your message. Please try again."
        );
      }
    } catch (err: any) {
      const serverError =
        err?.response?.data?.error ||
        err?.message ||
        "Failed to submit message. Please try again or reach out to support@trayago.in.";
      setErrorMsg(serverError);
    } finally {
      setLoading(false);
    }
  };

  const resetForm = () => {
    setFormData({
      name: "",
      email: "",
      phone: "",
      category: "general",
      subject: "",
      message: "",
    });
    setSubmitted(false);
    setErrorMsg(null);
  };

  return (
    <div className="min-h-screen bg-[var(--background)] px-4 py-12 sm:px-6 lg:px-8">
      <div className="max-w-6xl mx-auto">
        {/* Header Hero */}
        <div className="text-center max-w-3xl mx-auto mb-14">
          <div className="inline-flex items-center gap-2 px-3.5 py-1.5 rounded-full bg-primary/10 border border-primary/20 text-primary text-xs font-bold uppercase tracking-wider mb-4 animate-fade-in">
            <Headphones className="w-4 h-4" />
            <span>24x7 Trayago Support</span>
          </div>

          <h1 className="text-3xl sm:text-4xl lg:text-5xl font-black text-main tracking-tight mb-4">
            We are here to{" "}
            <span className="bg-gradient-to-r from-primary via-indigo-400 to-purple-400 bg-clip-text text-transparent">
              help you
            </span>
          </h1>

          <p className="text-secondary text-base sm:text-lg leading-relaxed">
            Have questions about split tickets, PNR prediction, refund policies,
            or custom integrations? Send us a direct message and our team will
            respond promptly.
          </p>
        </div>

        {/* Main Grid: Info Sidebar + Contact Form */}
        <div className="grid grid-cols-1 lg:grid-cols-12 gap-8 items-start">
          {/* Left Column: Direct Channels & SLA (5 cols) */}
          <div className="lg:col-span-5 space-y-6">
            {/* Direct Contact Card */}
            <div className="bg-card/60 backdrop-blur-xl border border-strong/40 rounded-3xl p-6 sm:p-8 shadow-xl">
              <h2 className="text-xl font-bold text-main mb-6 flex items-center gap-2.5">
                <Sparkles className="w-5 h-5 text-primary" />
                <span>Direct Channels</span>
              </h2>

              <div className="space-y-5">
                {/* Official Support Email */}
                <div className="flex items-start gap-4 p-4 rounded-2xl bg-card border border-subtle/40 hover:border-primary/40 transition-colors">
                  <div className="w-11 h-11 rounded-xl bg-primary/10 text-primary flex items-center justify-center shrink-0">
                    <Mail className="w-5 h-5" />
                  </div>
                  <div>
                    <p className="text-xs font-bold text-muted uppercase tracking-wider">
                      Customer Desk
                    </p>
                    <a
                      href="mailto:support@trayago.in"
                      className="text-base font-bold text-main hover:text-primary transition-colors block mt-0.5"
                    >
                      support@trayago.in
                    </a>
                    <p className="text-xs text-secondary mt-1">
                      Direct inbox monitored 24x7 for all queries
                    </p>
                  </div>
                </div>

                {/* Response SLA */}
                <div className="flex items-start gap-4 p-4 rounded-2xl bg-card border border-subtle/40">
                  <div className="w-11 h-11 rounded-xl bg-emerald-500/10 text-emerald-500 flex items-center justify-center shrink-0">
                    <Clock className="w-5 h-5" />
                  </div>
                  <div>
                    <p className="text-xs font-bold text-muted uppercase tracking-wider">
                      Turnaround SLA
                    </p>
                    <p className="text-base font-bold text-main mt-0.5">
                      Within 2 to 4 hours
                    </p>
                    <p className="text-xs text-secondary mt-1">
                      Priority triage for ticket and confirmation emergencies
                    </p>
                  </div>
                </div>

                {/* Direct Onboard Complaint Notice */}
                <div className="flex items-start gap-4 p-4 rounded-2xl bg-card border border-subtle/40">
                  <div className="w-11 h-11 rounded-xl bg-amber-500/10 text-amber-500 flex items-center justify-center shrink-0">
                    <ShieldCheck className="w-5 h-5" />
                  </div>
                  <div>
                    <p className="text-xs font-bold text-muted uppercase tracking-wider">
                      Onboard Emergency?
                    </p>
                    <p className="text-sm font-semibold text-main mt-0.5">
                      Need live assistance inside your coach?
                    </p>
                    <Link
                      href="/complaint"
                      className="inline-flex items-center gap-1.5 text-xs font-bold text-amber-500 hover:text-amber-400 mt-2"
                    >
                      <span>Open Train Complaint Assistant</span>
                      <ArrowRight className="w-3.5 h-3.5" />
                    </Link>
                  </div>
                </div>
              </div>
            </div>

            {/* Quick Tips Box */}
            <div className="bg-gradient-to-br from-primary/10 via-purple-500/5 to-transparent border border-primary/20 rounded-3xl p-6">
              <h3 className="text-sm font-bold text-main flex items-center gap-2 mb-2">
                <FileQuestion className="w-4 h-4 text-primary" />
                <span>Frequently Answered</span>
              </h3>
              <p className="text-xs text-secondary leading-relaxed mb-4">
                Looking for refund terms or PNR confirmation insights? You can
                also review our verified resources:
              </p>
              <div className="flex flex-wrap gap-2">
                <Link
                  href="/refund-policy"
                  className="text-xs font-semibold px-3 py-1.5 rounded-lg bg-card/80 border border-subtle/50 text-secondary hover:text-primary transition-colors"
                >
                  Refund Policy &rarr;
                </Link>
                <Link
                  href="/terms"
                  className="text-xs font-semibold px-3 py-1.5 rounded-lg bg-card/80 border border-subtle/50 text-secondary hover:text-primary transition-colors"
                >
                  Terms of Use &rarr;
                </Link>
                <Link
                  href="/pnr"
                  className="text-xs font-semibold px-3 py-1.5 rounded-lg bg-card/80 border border-subtle/50 text-secondary hover:text-primary transition-colors"
                >
                  PNR Status &rarr;
                </Link>
              </div>
            </div>
          </div>

          {/* Right Column: Interactive Form (7 cols) */}
          <div className="lg:col-span-7">
            <div className="bg-card/80 backdrop-blur-xl border border-strong/40 rounded-3xl p-6 sm:p-10 shadow-2xl">
              {submitted ? (
                /* Success State */
                <div className="py-12 px-4 text-center animate-fade-in">
                  <div className="w-20 h-20 rounded-3xl bg-emerald-500/10 text-emerald-500 border border-emerald-500/20 flex items-center justify-center mx-auto mb-6">
                    <CheckCircle2 className="w-10 h-10" />
                  </div>
                  <h3 className="text-2xl font-black text-main tracking-tight mb-2">
                    Message Sent Successfully!
                  </h3>
                  <p className="text-secondary text-sm sm:text-base max-w-md mx-auto mb-6">
                    Thank you, <strong className="text-main">{formData.name}</strong>.
                    Your inquiry has been delivered directly to the Trayago admin
                    desk. We will reply to{" "}
                    <span className="text-primary font-semibold">{formData.email}</span> shortly.
                  </p>
                  <button
                    onClick={resetForm}
                    className="inline-flex items-center gap-2 px-6 py-2.5 rounded-xl bg-primary text-white font-bold text-sm shadow-lg shadow-primary/25 hover:bg-primary/90 transition-all focus:outline-none focus:ring-2 focus:ring-primary"
                  >
                    Send Another Message
                  </button>
                </div>
              ) : (
                /* The Contact Form */
                <form onSubmit={handleSubmit} className="space-y-6">
                  <div>
                    <h2 className="text-xl sm:text-2xl font-black text-main tracking-tight">
                      Send a Direct Message
                    </h2>
                    <p className="text-xs sm:text-sm text-secondary mt-1">
                      Fill out the form below. Messages are routed straight to our
                      admin team.
                    </p>
                  </div>

                  {/* Error Alert */}
                  {errorMsg && (
                    <div className="p-4 rounded-xl bg-rose-500/10 border border-rose-500/30 text-rose-500 flex items-start gap-3 text-sm animate-shake">
                      <AlertCircle className="w-5 h-5 shrink-0 mt-0.5" />
                      <span>{errorMsg}</span>
                    </div>
                  )}

                  {/* Category Selector Chips */}
                  <div>
                    <label className="block text-xs font-black uppercase tracking-wider text-muted mb-2.5">
                      Select Topic / Inquiry Type
                    </label>
                    <div className="grid grid-cols-1 sm:grid-cols-2 gap-2.5">
                      {CATEGORIES.map((cat) => {
                        const Icon = cat.icon;
                        const isSelected = formData.category === cat.id;
                        return (
                          <button
                            type="button"
                            key={cat.id}
                            onClick={() => selectCategory(cat.id)}
                            className={`flex items-start gap-3 p-3 rounded-xl border text-left transition-all ${
                              isSelected
                                ? "bg-primary/15 border-primary text-main ring-1 ring-primary/40 shadow-sm"
                                : "bg-card/60 border-subtle/50 text-secondary hover:border-primary/30 hover:bg-card"
                            }`}
                          >
                            <Icon
                              className={`w-4 h-4 mt-0.5 shrink-0 ${
                                isSelected ? "text-primary" : "text-muted"
                              }`}
                            />
                            <div>
                              <div
                                className={`text-xs font-bold ${
                                  isSelected ? "text-main" : "text-secondary"
                                }`}
                              >
                                {cat.label}
                              </div>
                              <div className="text-[10px] text-muted line-clamp-1 mt-0.5">
                                {cat.description}
                              </div>
                            </div>
                          </button>
                        );
                      })}
                    </div>
                  </div>

                  {/* Name and Email Row */}
                  <div className="grid grid-cols-1 sm:grid-cols-2 gap-5">
                    <div>
                      <label
                        htmlFor="contact-name"
                        className="block text-xs font-black uppercase tracking-wider text-muted mb-2"
                      >
                        Your Name <span className="text-rose-500">*</span>
                      </label>
                      <input
                        id="contact-name"
                        name="name"
                        type="text"
                        required
                        value={formData.name}
                        onChange={handleInputChange}
                        placeholder="e.g. Rahul Sharma"
                        className="w-full px-4 py-2.5 rounded-xl bg-card border border-subtle focus:border-primary focus:ring-1 focus:ring-primary text-sm text-main placeholder-muted/60 transition-colors outline-none"
                      />
                    </div>

                    <div>
                      <label
                        htmlFor="contact-email"
                        className="block text-xs font-black uppercase tracking-wider text-muted mb-2"
                      >
                        Email Address <span className="text-rose-500">*</span>
                      </label>
                      <input
                        id="contact-email"
                        name="email"
                        type="email"
                        required
                        value={formData.email}
                        onChange={handleInputChange}
                        placeholder="rahul@example.com"
                        className="w-full px-4 py-2.5 rounded-xl bg-card border border-subtle focus:border-primary focus:ring-1 focus:ring-primary text-sm text-main placeholder-muted/60 transition-colors outline-none"
                      />
                    </div>
                  </div>

                  {/* Phone and Subject Row */}
                  <div className="grid grid-cols-1 sm:grid-cols-2 gap-5">
                    <div>
                      <label
                        htmlFor="contact-phone"
                        className="block text-xs font-black uppercase tracking-wider text-muted mb-2"
                      >
                        Phone / WhatsApp (Optional)
                      </label>
                      <input
                        id="contact-phone"
                        name="phone"
                        type="tel"
                        value={formData.phone}
                        onChange={handleInputChange}
                        placeholder="+91 98765 43210"
                        className="w-full px-4 py-2.5 rounded-xl bg-card border border-subtle focus:border-primary focus:ring-1 focus:ring-primary text-sm text-main placeholder-muted/60 transition-colors outline-none"
                      />
                    </div>

                    <div>
                      <label
                        htmlFor="contact-subject"
                        className="block text-xs font-black uppercase tracking-wider text-muted mb-2"
                      >
                        Subject <span className="text-rose-500">*</span>
                      </label>
                      <input
                        id="contact-subject"
                        name="subject"
                        type="text"
                        required
                        value={formData.subject}
                        onChange={handleInputChange}
                        placeholder="Brief summary of your question"
                        className="w-full px-4 py-2.5 rounded-xl bg-card border border-subtle focus:border-primary focus:ring-1 focus:ring-primary text-sm text-main placeholder-muted/60 transition-colors outline-none"
                      />
                    </div>
                  </div>

                  {/* Message Field */}
                  <div>
                    <div className="flex justify-between items-center mb-2">
                      <label
                        htmlFor="contact-message"
                        className="block text-xs font-black uppercase tracking-wider text-muted"
                      >
                        Message <span className="text-rose-500">*</span>
                      </label>
                      <span className="text-[11px] text-muted">
                        {formData.message.length}/5000
                      </span>
                    </div>
                    <textarea
                      id="contact-message"
                      name="message"
                      required
                      rows={5}
                      maxLength={5000}
                      value={formData.message}
                      onChange={handleInputChange}
                      placeholder="Please write your detailed question or requirement here..."
                      className="w-full px-4 py-3 rounded-xl bg-card border border-subtle focus:border-primary focus:ring-1 focus:ring-primary text-sm text-main placeholder-muted/60 transition-colors outline-none resize-y"
                    />
                  </div>

                  {/* Submit Button */}
                  <div>
                    <button
                      type="submit"
                      disabled={loading}
                      className="w-full py-3.5 px-6 rounded-xl bg-gradient-to-r from-primary to-indigo-600 hover:from-primary/95 hover:to-indigo-500 text-white font-bold text-sm shadow-xl shadow-primary/20 flex items-center justify-center gap-2 transition-all disabled:opacity-50 disabled:cursor-not-allowed focus:outline-none focus:ring-2 focus:ring-primary focus:ring-offset-2"
                    >
                      {loading ? (
                        <>
                          <Loader2 className="w-4 h-4 animate-spin" />
                          <span>Delivering your message...</span>
                        </>
                      ) : (
                        <>
                          <Send className="w-4 h-4" />
                          <span>Submit Message to Admin</span>
                        </>
                      )}
                    </button>
                    <p className="text-[11px] text-muted text-center mt-3">
                      🔒 Your contact information is kept confidential and only
                      used to respond to your inquiry.
                    </p>
                  </div>
                </form>
              )}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}
